    "hotelNote": "2名1室・朝食付きで12泊。上海に最初の2泊と最後の1泊、武陵源2泊、張家界市内1泊、鳳凰2泊、桂林2泊、陽朔2泊です。4つ星相当（Trip.com／携程の4ダイヤ）のホテルがある都市ではそれを基準とし、鳳凰では川沿いで評価の最も高いホテルを選んで、お支払い前にお知らせします。",
