    "hotelNote": "2名1室・朝食付きで9泊。4つ星相当（Trip.com／携程の4ダイヤ）を基準に、北京3泊、西安2泊、桂林1泊、陽朔2泊、香港1泊です。香港の客室は、同じクラスでも中国本土より狭いのが一般的です。ホテル名と客室タイプはお支払い前に確認します。",
    "serviceNote": "中国本土の各都市の観光日は、現地の英語ガイドと車両がお客様のグループ専用です。全送迎（香港西九龍駅からホテル、ホテルから空港まで）、記載施設の基本入場券、漓江クルーズと荷物の別車輸送、北京―西安と桂林―香港の高速鉄道2等席、西安―桂林のエコノミークラス便を含みます。ガイドは都市ごとに交代し、列車や航空便の移動日は、出発地のドライバーが駅や空港までお送りし、到着地では別のドライバーがお迎えします。日本語ガイドの手配可否と料金は予約前に確認します。",
