    "bookingNote": "掲載価格は、記載の参加人数で2名1室を利用した場合の1名あたりの最低料金です。日程が決まったら、故宮、兵馬俑、列車の予約に必要なパスポート情報をお知らせいただき、桂林―香港の高速鉄道は発売と同時に予約します。トランジットビザ免除を利用する予定の方は、どこから中国本土に入るかを確認し、出発前に香港行きの確定した乗車券をお持ちください。ビザの申請代行は行っていません。航空便、列車、ホテル、最終総額はお支払い前に書面で確認します。",
